package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;
final class AssistantEvaluationsBrowserAcceptance {
 static void click(Page p,String label){ServiceOutagesBrowserAcceptance.click(p,label);}
 static void run(BrowserTest h)throws Exception{
  String article;try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);article=KnowledgeSearchAcceptance.article(db,actor,"Evaluation browser guidance","Submit the approved request form <script>source</script>");db.connection.commit();}
  try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.store.environment);var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   provider.settings.put("AI_KNOWLEDGE_ENABLED","true");provider.answer.set("Submit the approved request form <script>answer</script>");var page=context.newPage();h.login(page,"admin");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Assistant evaluations")).press("Enter");page.getByLabel("Dataset name").fill("Knowledge answer qualification");page.getByLabel("Version label").fill("v1");page.getByLabel("Cohort").selectOption("held_out");page.getByLabel("Dataset provenance").fill("Predeclared synthetic browser acceptance cases; not production qualification");page.getByLabel("Evaluation cases (JSON)").fill(JSON.writeValueAsString(List.of(map("article_id",article,"question","How do I request help?","expected_answer","WITHHELD request form answer"))));click(page,"Seal evaluation dataset");String suite=page.url();assertThat(page.locator("main")).containsText("Knowledge answer qualification");click(page,"Start evaluation run");click(page,"Preview case");assertEquals(0,provider.calls.get());assertTrue(page.locator("input[name=allow_external]").boundingBox().width<25);assertThat(page.locator("main")).containsText("Review exact external context");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/evaluation-preview-light.png")).setFullPage(true));page.getByLabel("Send this published source and question to the configured provider").check();click(page,"Run reviewed case");assertThat(page.locator("main")).containsText(provider.answer.get());assertFalse(provider.captured.get().contains("WITHHELD"));assertThat(page.locator("main script")).hasCount(0);page.getByLabel("Acceptable answer").selectOption("true");page.getByLabel("Grounded in the source").selectOption("true");page.getByLabel("Correction needed").selectOption("false");page.getByLabel("Grading rationale").fill("Answer matches the source and expected request-form outcome");click(page,"Save human grade");click(page,"Finish and seal results");assertThat(page.locator("main")).containsText("1 / 1 cases passed (100.0%)");assertThat(page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save human grade"))).hasCount(0);click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/evaluation-completed-dark.png")).setFullPage(true));String export=page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Open evaluation JSON")).getAttribute("href");var response=context.request().get(h.base()+export);assertEquals(200,response.status());assertTrue(response.text().contains("WITHHELD"));assertTrue(response.text().contains("knowledge-question.v1"));assertFalse(response.text().contains("proof"));
   try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);PublishedKnowledge.retire(db,actor,article);db.connection.commit();}assertEquals(404,context.request().get(h.base()+export).status());page.navigate(suite);assertThat(page.locator("main")).not().containsText(provider.answer.get());page.navigate(h.base()+"/admin/ai-evaluations");var owned=page.locator("article").filter(new Locator.FilterOptions().setHasText("Knowledge answer qualification"));owned.getByLabel("Delete this suite and all its runs").check();owned.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Delete suite")).press("Enter");assertThat(page.locator("main")).not().containsText("Knowledge answer qualification");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/evaluation-deleted-dark.png")).setFullPage(true));assertEquals(1,provider.calls.get());
  }
 }
}
